data.outputText:
{
  "generation_intent": {
    "goal": "Create a high-end, original fragrance campaign image that fuses the architectural minimalism of the product with a dramatic, macro-floral chiaroscuro environment, utilizing the specific reaching pose and striking platinum-blonde talent.",
    "approach": "MASTER_COORDINATOR dictates a mood of sensual minimalism and high-contrast luxury. REF_PRODUCT anchors the foreground with structural precision. REF_TALENT and REF_POSE provide the striking human element and dynamic composition (lying flat, reaching forward). REF_OUTFIT supplies the stark white sartorial contrast and gold sculptural accents. REF_ENVIRONMENT_MOOD transforms the setting into an abstract, velvety world of deep blue and violet iris petal textures emerging from pure darkness.",
    "originality_rule": "This must be a completely new composition. Do not replicate the source images. Synthesize the macro floral textures, the dynamic foreshortened pose, and the strict brand aesthetic into a unified, believable luxury fragrance advertisement."
  },
  "master_direction": {
    "brand_dna": "ARMANI beauty: The intersection of high-fashion heritage and modern cosmetic precision. Sensual minimalism, intellectual allure, timeless grace, and the powerful magnetism of the unsaid. A masterclass in visual tension: architectural rigidity meeting organic sensuality.",
    "message_coherence": "Quiet, supreme confidence. The image must utilize profound restraint, generous negative space, and stark monochrome foundations punctuated only by the specific product colors and environmental jewel tones. The feeling is cultured, authoritative, precise, and intimate.",
    "non_negotiable_rules": [
      "The product design, proportions, and branding must remain absolutely unadulterated.",
      "The visual language must rely on modern chiaroscuro, carving shapes from deep shadows.",
      "Lighting must emphasize the weight and purity of materials (heavy glass, smooth obsidian-like resin, pale gold).",
      "The image must never appear cluttered, overly decorative, or mass-market.",
      "Avoid hyper-saturated, flat, or overly accessible visual tropes; maintain a luxurious, cinematic depth."
    ]
  },
  "environment_mood": {
    "location_identity": "An abstract, sensual, macro-floral void. The surface the talent lies on and the surrounding background consist of monumental, sweeping, velvety folds that mimic the organic, ruffled texture of a macro iris petal.",
    "background_feeling": "A deep, infinite black space out of which rich, luminescent textures of deep indigo, vibrant violet, and cerulean blue emerge. The environment feels tactile, organic, and incredibly intimate, wrapping the scene in a quiet, dark elegance.",
    "atmospheric_direction": "Cinematic, mysterious, and highly textural. The atmosphere is heavy with the implied scent of the iris, utilizing deep shadows and rich, cool-toned ambient reflections to create a mood of nocturnal luxury.",
    "brand_alignment": "The dark, organic folds perfectly contrast with the stark white of the wardrobe and the architectural geometry of the glass flacon, fulfilling the brand's mandate of tension between the organic and the structured."
  },
  "talent": {
    "identity": "A young woman with striking, delicate features, pale skin with subtle natural freckles, piercing blue eyes, and soft, full natural lips.",
    "appearance": "Ethereal yet intensely present. Her pale complexion and icy hair create a stark, luminous contrast against the deep, dark floral environment.",
    "hair": "Icy platinum blonde, styled in a choppy, textured layered bob with heavy, sweeping bangs that partially obscure one eye, catching crisp, cool highlights.",
    "pose": "Lying flat on her back on the velvety, petal-like surface. Her head is turned in semi-profile. One arm is extended directly upward and toward the camera lens in dramatic foreshortening, hand splayed wide with relaxed, elegant tension, visually interacting with or framing the perfume bottle placed in the immediate foreground.",
    "expression": "Calm, enigmatic, and supremely confident. A look of quiet intellectual allure with parted lips.",
    "gaze": "Looking slightly off-camera or piercing softly through the sweeping bangs, projecting an intimate, magnetic pull.",
    "attitude": "Effortlessly luxurious, embodying the quiet certainty of a heritage house and the sensual grace of the brand."
  },
  "product": {
    "identity": "Armani Prive Iris Bleu fragrance flacon.",
    "category": "Luxury niche fragrance bottle.",
    "design_integrity_rule": "The product's geometry, cap shape, label proportions, and material finishes must be rendered with absolute architectural fidelity. No alterations to its form are permitted.",
    "visible_structure": "A heavy, rectangular base of pristine, thick transparent glass containing a light, watery blue liquid. The cap is a large, asymmetrical, smooth, pebble-like organic shape that overhangs the bottle's neck. A perfectly square, slightly recessed plaque sits on the front face of the glass.",
    "materials": [
      "Heavy, architectural, crystal-clear glass with thick base and walls.",
      "Smooth, highly polished, opaque black resin/obsidian for the organic cap.",
      "Brushed pale gold for the square front plaque and the subtle collar beneath the cap.",
      "Translucent light blue liquid."
    ],
    "surface_finish": "The glass must exhibit highly realistic refractive properties and heavy edge thickness. The black cap must catch smooth, curved, specular highlights that define its organic, pebble-like volume. The gold plaque should have a refined, muted metallic sheen.",
    "branding_and_signature_details": [
      "The square pale gold plaque must feature the precise, high-contrast black serif text 'IRIS' over 'BLEU', with 'ARMANI/PRIVE' below it in a smaller, tracked-out geometric sans-serif.",
      "The tension between the strict rectangular glass and the flowing, asymmetrical black cap is the defining signature and must be perfectly captured."
    ],
    "consistency_rule": "The bottle must remain instantly recognizable as the exact Armani Prive Iris Bleu product, maintaining its precise proportions and material contrasts regardless of the foreground placement or dramatic lighting."
  },
  "wardrobe": {
    "outfit_overview": "A pristine, minimalist matte white bodysuit paired with opaque white tights, serving as a stark, clean canvas that contrasts sharply with the dark environment.",
    "materials": [
      "Matte, high-quality stretch fabric (like a dense jersey or fine activewear knit) for the bodysuit and tights.",
      "Polished, heavy pale gold for the sculptural jewelry."
    ],
    "construction_details": [
      "Form-fitting silhouette with clean, invisible seams.",
      "The extended hand is adorned with large, organic, sculptural pale gold rings and a matching interlocking bracelet, echoing the organic shape of the perfume cap and the gold of the label."
    ],
    "fit_and_behavior": "The white fabric stretches smoothly over the talent's reclining form, catching crisp, clean light and providing a striking architectural shape within the organic folds of the blue/purple environment."
  },
  "lighting": {
    "setup": "Modern, sculptural chiaroscuro. A precise, cool-toned directional key light rakes across the platinum hair, the white bodysuit, and the extended arm, carving them out of the pure black background. A dedicated, highly controlled secondary light shapes the perfume bottle in the foreground, highlighting the heavy glass edges and creating a smooth, wrapping reflection on the black pebble cap.",
    "effects": [
      "Deep, enveloping shadows that fade into pure black.",
      "Subtle, rich blue and violet ambient bounce light reflecting off the velvety petal-like ground surfaces.",
      "Crisp, precise specular highlights on the gold rings and the product's gold plaque.",
      "Caustic light refractions passing through the thick glass bottle and the blue liquid onto the dark surface."
    ],
    "color_grading": "A sophisticated, cool-leaning luxury palette. Deep, crushing blacks, stark pure whites, icy platinum tones, and rich, saturated jewel tones (indigo, violet, iris blue) in the shadows. The pale gold accents provide the only warm counterpoint."
  },
  "camera_language": {
    "shot_feeling": "A dramatic, intimate, and highly structural luxury campaign photograph.",
    "framing_logic": "Low angle, shooting past the majestic perfume bottle in the immediate foreground, looking up the dramatically foreshortened extended arm of the talent lying in the midground. The composition uses the arm to lead the eye directly from the product to the talent's face.",
    "editorial_style": "High-fashion beauty editorial meets architectural product photography. Extremely deliberate, utilizing scale, perspective, and negative space to create visual magnetism."
  },
  "photographic_finish": {
    "capture_character": "High-end medium-format digital capture with a cinematic, slightly analog tonal response.",
    "film_or_sensor_feel": "Incredibly clean and sharp at the focal plane, with a smooth, expensive-feeling focus falloff. The shadows are dense but hold subtle color information.",
    "grain_structure": "Very fine, tightly packed, organic photographic grain that adds subtle physical texture without compromising the pristine nature of the product.",
    "contrast_response": "High global contrast (bright whites against deep blacks) but with soft, sophisticated micro-contrast that preserves delicate transitions in the skin and the dark velvety fabrics.",
    "skin_rendering_rule": "Skin must appear natural, soft-matte to satin, showing real, fine pores and subtle freckles. Highlights on the skin should be broad and soft, driven by the environment. Absolutely no plastic sheen, over-sharpening, or synthetic beauty-filter smoothness.",
    "scan_or_border_behavior": "Full bleed, clean modern presentation. No borders."
  },
  "realism_focus": {
    "textures": [
      "The micro-ribbing and organic, velvety folds of the dark blue/purple iris petal environment.",
      "The icy, individual strands of the choppy platinum blonde hair.",
      "The dense, matte, light-absorbing quality of the white bodysuit.",
      "The smooth, flawless, obsidian-like surface of the perfume cap.",
      "The heavy, cold, refractive index of the thick glass bottle."
    ],
    "imperfections": [
      "Subtle, natural variations in the talent's skin tone and freckles.",
      "Slight, realistic creases in the white fabric at the joints of the extended arm.",
      "Organic irregularities in the velvety texture of the floral background, preventing it from looking like a flat digital render."
    ]
  }
}

